import BrandsSectionV3 from "./components/brands-section-v3"

export default function Page() {
  return <BrandsSectionV3 />
}

import BrandGrid from "./brand-grid"

import "../styles/brands-section-v3.css"

export default function BrandsSectionV3() {
  return (
    <section className="mx-auto max-w-4xl px-4 py-4 md:py-6 lg:py-8">
      <BrandGrid />
    </section>
