}

"use client"

import { brands } from "../lib/brands"
import { BrandCell } from "./brand-cell"

export default function BrandGrid() {
  return (
    <div
      className="grid grid-cols-2 border border-border sm:grid-cols-3 lg:grid-cols-6"
      role="list"
      aria-label="Technology partner logos"
    >
      {brands.map((brand) => (
        <BrandCell key={brand.name} brand={brand} />
      ))}
    </div>
  )
}

"use client"

import { useEffect, useState, type CSSProperties } from "react"

import { FlickeringGrid } from "./flickering-grid"
import type { Brand } from "../lib/brands"

export function BrandCell({ brand }: { brand: Brand }) {
  const Icon = brand.Icon
  const DarkIcon = brand.darkIcon ?? brand.Icon
  const [isHovered, setIsHovered] = useState(false)
  const [coarsePointer, setCoarsePointer] = useState(false)

  useEffect(() => {
    const mq = window.matchMedia("(hover: none)")
    const update = () => setCoarsePointer(mq.matches)
    update()
    mq.addEventListener("change", update)
    return () => mq.removeEventListener("change", update)
  }, [])

  const gridActive = isHovered || coarsePointer

  return (
    <div
      aria-label={brand.name}
      className="bs3-cell group relative isolate z-0 -mt-px -ml-px flex cursor-default items-center justify-center overflow-hidden border border-border bg-background py-8 outline-none hover:z-10 focus-visible:z-10"
      role="listitem"
      style={{ "--bs3-brand-color": brand.color } as CSSProperties}
      tabIndex={0}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onFocus={() => setIsHovered(true)}
      onBlur={() => setIsHovered(false)}
    >
      <div className="bs3-flicker-layer" aria-hidden>
        <FlickeringGrid
          active={gridActive}
          className="h-full w-full mask-[radial-gradient(ellipse_75%_70%_at_50%_50%,white,transparent)]"
          color={brand.color}
        />
      </div>

      <div className="relative z-10 flex w-full flex-col items-center">
        <div className="bs3-logo-stack relative aspect-square w-10 max-w-full translate-y-4 transition-transform delay-130 duration-480 ease-[cubic-bezier(0.22,1,0.36,1)] group-hover:translate-y-0 group-hover:delay-0 group-focus-visible:translate-y-0 group-focus-visible:delay-0 md:w-12">
          <span className="bs3-icon-default">
            <Icon aria-hidden className="h-full w-full" />
          </span>
          <span className="bs3-icon-hover">
            <Icon aria-hidden className="h-full w-full dark:hidden" />
            <DarkIcon aria-hidden className="hidden h-full w-full dark:block" />
          </span>
        </div>

        <span className="bs3-name-label mt-2 text-sm font-medium tracking-wide text-foreground">
          {brand.name}
        </span>
      </div>
    </div>
  )
}

"use client"

import { cn } from "@/lib/utils"
import { useEffect, useRef } from "react"

export type FlickeringGridProps = {
  className?: string
  squareSize?: number
  gridGap?: number
  color?: string
  maxOpacity?: number
  flickerChance?: number
  active?: boolean
  flickerFrameSkip?: number
  opacityLerp?: number
}

function parseRgb(hex: string): [number, number, number] {
  const h = hex.replace("#", "")
  const full =
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h
  if (full.length !== 6) {
    return [96, 165, 250]
  }
  return [
    Number.parseInt(full.slice(0, 2), 16),
    Number.parseInt(full.slice(2, 4), 16),
    Number.parseInt(full.slice(4, 6), 16),
  ]
}

type Dims = { w: number; h: number; cols: number; rows: number }

export function FlickeringGrid({
  className,
  squareSize = 4,
  gridGap = 6,
  color = "#60A5FA",
  maxOpacity = 0.45,
  flickerChance = 0.03,
  active = true,
  flickerFrameSkip = 10,
  opacityLerp = 0.05,
}: FlickeringGridProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const currentRef = useRef<number[]>([])
  const targetRef = useRef<number[]>([])
  const dimsRef = useRef<Dims>({ w: 1, h: 1, cols: 1, rows: 1 })
  const rafRef = useRef(0)
  const frameRef = useRef(0)

  useEffect(() => {
    const container = containerRef.current
    const canvas = canvasRef.current
    if (!container || !canvas) {
      return
    }

    const ctx = canvas.getContext("2d")
    if (!ctx) {
      return
    }

    const [r, g, b] = parseRgb(color)
    const cell = squareSize + gridGap

    const syncDimensions = () => {
      const rect = container.getBoundingClientRect()
      const w = Math.max(1, Math.floor(rect.width))
      const h = Math.max(1, Math.floor(rect.height))
      const dpr = window.devicePixelRatio || 1
      canvas.width = w * dpr
      canvas.height = h * dpr
      canvas.style.width = `${w}px`
      canvas.style.height = `${h}px`
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)

      const cols = Math.max(1, Math.ceil(w / cell))
      const rows = Math.max(1, Math.ceil(h / cell))
      const len = cols * rows
      const prevC = currentRef.current
      const prevT = targetRef.current
      const nextC = new Array<number>(len)
      const nextT = new Array<number>(len)
      for (let i = 0; i < len; i++) {
        const c = prevC[i] ?? Math.random() * maxOpacity * 0.4
        const t = prevT[i] ?? c
        nextC[i] = c
        nextT[i] = t
      }
      currentRef.current = nextC
      targetRef.current = nextT
      dimsRef.current = { w, h, cols, rows }
    }

    const tick = () => {
      if (!active) {
        return
      }

      const { w, h, cols, rows } = dimsRef.current
      const current = currentRef.current
      const target = targetRef.current

      frameRef.current += 1
      if (frameRef.current % flickerFrameSkip === 0) {
        for (let row = 0; row < rows; row++) {
          for (let col = 0; col < cols; col++) {
            const idx = row * cols + col
            if (idx >= target.length) {
              continue
            }
            if (Math.random() < flickerChance) {
              target[idx] = Math.random() * maxOpacity
            }
          }
        }
      }

      ctx.clearRect(0, 0, w, h)

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const idx = row * cols + col
          if (idx >= current.length) {
            continue
          }
          const t = target[idx]
          const c = current[idx]
          current[idx] = c + (t - c) * opacityLerp
          const o = current[idx]
          const x = col * cell + gridGap / 2
          const y = row * cell + gridGap / 2
          ctx.fillStyle = `rgba(${r},${g},${b},${o})`
          ctx.fillRect(x, y, squareSize, squareSize)
        }
      }

      rafRef.current = requestAnimationFrame(tick)
    }

    const ro = new ResizeObserver(() => {
      syncDimensions()
    })
    ro.observe(container)
    syncDimensions()

    if (active) {
      rafRef.current = requestAnimationFrame(tick)
    }

    return () => {
      ro.disconnect()
      cancelAnimationFrame(rafRef.current)
    }
  }, [
    active,
    color,
    squareSize,
    gridGap,
    maxOpacity,
    flickerChance,
    flickerFrameSkip,
    opacityLerp,
  ])

  return (
    <div
      ref={containerRef}
      className={cn("relative h-full min-h-px w-full min-w-px", className)}
    >
      <canvas
        ref={canvasRef}
        className="pointer-events-none absolute inset-0 z-0 block h-full w-full"
        aria-hidden
      />
    </div>
  )
}

.bs3-cell {
  --bs3-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.bs3-cell::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, var(--background) 0%, transparent 84%);
  pointer-events: none;
  z-index: 1;
}

.bs3-cell::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  box-shadow: inset 0 0 0 1px transparent;
  transition: box-shadow 300ms 150ms ease;
}

.bs3-cell:hover::after,
.bs3-cell:focus-visible::after {
  box-shadow: inset 0 0 0 1px var(--bs3-brand-color);
  transition: box-shadow 300ms 0ms ease;
}

.bs3-flicker-layer {
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: hidden;
  pointer-events: none;
  opacity: 0;
  transition: opacity 300ms ease-out;
}

.bs3-cell:hover .bs3-flicker-layer,
.bs3-cell:focus-visible .bs3-flicker-layer {
  opacity: 1;
}

.bs3-icon-default,
.bs3-icon-hover {
  position: absolute;
  inset: 0;
  display: flex;
}

.bs3-icon-default {
  opacity: 1;
  filter: grayscale(1) opacity(0.35) blur(0);
  transition:
    opacity 520ms var(--bs3-ease) 120ms,
    filter 520ms var(--bs3-ease) 120ms;
}

.dark .bs3-icon-default {
  filter: grayscale(1) invert(1) opacity(0.22) blur(0);
}

.bs3-cell:hover .bs3-icon-default,
.bs3-cell:focus-visible .bs3-icon-default {
  opacity: 0;
  pointer-events: none;
  filter: grayscale(1) opacity(0) blur(5px);
  transition-delay: 0ms, 0ms;
}

.dark .bs3-cell:hover .bs3-icon-default,
.dark .bs3-cell:focus-visible .bs3-icon-default {
  filter: grayscale(1) invert(1) opacity(0) blur(5px);
}

.bs3-icon-hover {
  opacity: 0;
  filter: blur(6px);
  transition:
    opacity 540ms var(--bs3-ease) 45ms,
    filter 580ms var(--bs3-ease) 45ms;
}

.bs3-cell:hover .bs3-icon-hover,
.bs3-cell:focus-visible .bs3-icon-hover {
  opacity: 1;
  filter: blur(0);
  transition-delay: 70ms, 70ms;
}

.bs3-name-label {
  opacity: 0;
  filter: blur(5px);
  transform: translateY(0.375rem);
  transition:
    opacity 500ms var(--bs3-ease) 100ms,
    filter 500ms var(--bs3-ease) 100ms,
    transform 500ms var(--bs3-ease) 100ms;
}

.bs3-cell:hover .bs3-name-label,
.bs3-cell:focus-visible .bs3-name-label {
  opacity: 1;
  filter: none;
  transform: translateY(0);
  transition-delay: 95ms, 95ms, 95ms;
}

@media (prefers-reduced-motion: reduce) {
  .bs3-logo-stack {
    transition-duration: 0.01ms;
    transition-delay: 0ms !important;
  }

  .bs3-icon-default,
  .bs3-icon-hover {
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
  }

  .bs3-icon-default {
    filter: grayscale(1) opacity(0.35) blur(0) !important;
  }

  .dark .bs3-icon-default {
    filter: grayscale(1) invert(1) opacity(0.22) blur(0) !important;
  }

  .bs3-cell:hover .bs3-icon-default,
  .bs3-cell:focus-visible .bs3-icon-default {
    filter: grayscale(1) opacity(0) blur(0) !important;
  }

  .dark .bs3-cell:hover .bs3-icon-default,
  .dark .bs3-cell:focus-visible .bs3-icon-default {
    filter: grayscale(1) invert(1) opacity(0) blur(0) !important;
  }

  .bs3-icon-hover {
    filter: blur(0) !important;
  }

  .bs3-cell:hover .bs3-icon-hover,
  .bs3-cell:focus-visible .bs3-icon-hover {
    filter: blur(0) !important;
  }

  .bs3-name-label {
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
    filter: blur(0) !important;
    transform: none !important;
  }

  .bs3-cell:hover .bs3-icon-default,
  .bs3-cell:focus-visible .bs3-icon-default,
  .bs3-cell:hover .bs3-icon-hover,
  .bs3-cell:focus-visible .bs3-icon-hover,
  .bs3-cell:hover .bs3-name-label,
  .bs3-cell:focus-visible .bs3-name-label {
    transition-delay: 0ms !important;
  }
}

.bs3-cell:nth-child(2n) {
  border-right: none;
}
.bs3-cell:nth-last-child(-n + 2) {
  border-bottom: none;
}

@media (min-width: 640px) {
  .bs3-cell:nth-child(2n) {
    border-right: 1px solid var(--border);
  }
  .bs3-cell:nth-child(3n) {
    border-right: none;
  }
  .bs3-cell:nth-last-child(-n + 2) {
    border-bottom: 1px solid var(--border);
  }
  .bs3-cell:nth-last-child(-n + 3) {
    border-bottom: none;
  }
}

@media (min-width: 1024px) {
  .bs3-cell {
    border-right: 1px solid var(--border);
    border-bottom: none;
  }
  .bs3-cell:nth-child(3n) {
    border-right: 1px solid var(--border);
  }
  .bs3-cell:last-child {
    border-right: none;
  }
}

@media (hover: none) {
  .bs3-cell::after {
    box-shadow: inset 0 0 0 1px var(--bs3-brand-color);
    transition: none;
  }

  .bs3-cell .bs3-flicker-layer {
    opacity: 1;
    transition: none;
  }
  .bs3-cell .bs3-logo-stack {
    transform: translateY(0);
    transition: none;
  }

  .bs3-cell .bs3-icon-default {
    opacity: 0;
    filter: grayscale(1) opacity(0);
    transition: none;
  }

  .dark .bs3-cell .bs3-icon-default {
    filter: grayscale(1) invert(1) opacity(0);
  }

  .bs3-cell .bs3-icon-hover {
    opacity: 1;
    filter: none;
    transition: none;
  }

  .bs3-cell .bs3-name-label {
    opacity: 1;
    filter: none;
    transform: none;
    transition: none;
  }
}

import type { SVGProps } from "react";

const Vercel = (props: SVGProps<SVGSVGElement>) => (
  <svg {...props} viewBox="0 0 256 222" preserveAspectRatio="xMidYMid">
    <path d="m128 0 128 221.705H0z" />
  </svg>
);

export { Vercel };

import type { SVGProps } from "react";

const VercelDark = (props: SVGProps<SVGSVGElement>) => (
  <svg {...props} viewBox="0 0 256 222" preserveAspectRatio="xMidYMid">
    <path fill="#fff" d="m128 0 128 221.705H0z" />
  </svg>
);

export { VercelDark };
